//go:build amd64 && !purego
// +build amd64,!purego

#include "textflag.h"

#define SSE_LOOKUP_FIRST(IDX, OFF, STATE, ACC) \
	PEXTRB	$IDX, STATE, AX; \
	SHLQ	$4, AX; \
	MOVOU	OFF(DX)(AX*1), ACC

#define SSE_LOOKUP_XOR(IDX, OFF, STATE, ACC, TMP) \
	PEXTRB	$IDX, STATE, AX; \
	SHLQ	$4, AX; \
	MOVOU	OFF(DX)(AX*1), TMP; \
	PXOR	TMP, ACC

#define SSE_LOOKUP_BLOCK(STATE, ACC, TMP) \
	SSE_LOOKUP_FIRST(0, 0, STATE, ACC); \
	SSE_LOOKUP_XOR(1, 4096, STATE, ACC, TMP); \
	SSE_LOOKUP_XOR(2, 8192, STATE, ACC, TMP); \
	SSE_LOOKUP_XOR(3, 12288, STATE, ACC, TMP); \
	SSE_LOOKUP_XOR(4, 16384, STATE, ACC, TMP); \
	SSE_LOOKUP_XOR(5, 20480, STATE, ACC, TMP); \
	SSE_LOOKUP_XOR(6, 24576, STATE, ACC, TMP); \
	SSE_LOOKUP_XOR(7, 28672, STATE, ACC, TMP); \
	SSE_LOOKUP_XOR(8, 32768, STATE, ACC, TMP); \
	SSE_LOOKUP_XOR(9, 36864, STATE, ACC, TMP); \
	SSE_LOOKUP_XOR(10, 40960, STATE, ACC, TMP); \
	SSE_LOOKUP_XOR(11, 45056, STATE, ACC, TMP); \
	SSE_LOOKUP_XOR(12, 49152, STATE, ACC, TMP); \
	SSE_LOOKUP_XOR(13, 53248, STATE, ACC, TMP); \
	SSE_LOOKUP_XOR(14, 57344, STATE, ACC, TMP); \
	SSE_LOOKUP_XOR(15, 61440, STATE, ACC, TMP)

TEXT ·xorKeyStreamSSEBlocks(SB), NOSPLIT, $16-40
	MOVQ	buf+0(FP), R12
	MOVQ	buf_len+8(FP), R13
	SHRQ	$4, R13
	JZ	cmSSEDone

	MOVQ	iv+24(FP), R9
	MOVQ	R9, R14
	BSWAPQ	R14
	MOVQ	rkeys+32(FP), R10
	LEAQ	·lsEncLookup(SB), DX

cmSSEBlock:
	MOVQ	R9, R15
	BSWAPQ	R15
	MOVQ	R15, 0(SP)
	MOVQ	R14, 8(SP)
	MOVOU	(SP), X0
	MOVOU	(R12), X5
	MOVQ	R10, SI
	MOVQ	$9, DI

cmSSERound:
	MOVOU	(SI), X1
	PXOR	X1, X0
	SSE_LOOKUP_BLOCK(X0, X2, X3)
	ADDQ	$16, SI
	MOVOU	X2, X0
	SUBQ	$1, DI
	JNZ	cmSSERound

	MOVOU	(SI), X1
	PXOR	X1, X0
	PXOR	X0, X5
	MOVOU	X5, (R12)

	ADDQ	$16, R12
	ADDQ	$1, R9
	SUBQ	$1, R13
	JNZ	cmSSEBlock

cmSSEDone:
	RET
